-- Editor-facing data for the GayOut pipeline. This seed changes no schema.
-- Prepared during the coordinated migration hold; do not apply until released.
-- Human rewrites remain authoritative when a key already exists.
insert into public.pipeline_explanations(key,title,body,what_now,severity) values
('pipeline-validate:E_GAYOUT_COUNTRY_UNRESOLVED','Country could not be matched',
 'The GayOut country path could not be mapped to a recognised country code. The record has not been committed with a guessed country.',
 'Check the source URL and country mapping before retrying the listing.','blocking'),
('pipeline-validate:E_GAYOUT_DOCUMENT_TOO_LARGE','Source document exceeds the size limit',
 'A source response exceeded the 25 MB document limit. It was stopped before it could be treated as a complete inventory or detail page.',
 'Inspect the source response and use smaller source sitemap files where available.','blocking'),
('pipeline-validate:E_GAYOUT_PROVIDER_QUOTA','Extraction provider credits are exhausted',
 'The configured Firecrawl account returned HTTP 402. The source could not be retrieved, and the pipeline retained its checkpoints instead of reporting an empty successful sync.',
 'Restore credits or configure an authorised account with available credits, then restart the GayOut sync.','blocking'),
('pipeline-validate:E_GAYOUT_PROVIDER_UNAVAILABLE','Extraction provider is unavailable',
 'Firecrawl returned an unsuccessful response while retrieving a GayOut source document. This does not establish that the source listing is empty or removed.',
 'Check the provider response and service status, then retry after access is restored.','blocking'),
('pipeline-validate:E_GAYOUT_RATE_LIMIT','Source requested a later retry',
 'GayOut or the extraction provider returned HTTP 429. The affected URLs are deferred according to the published retry delay; their existing content is preserved.',
 'Allow the delayed retry to run. If limits persist, reduce request frequency or review the provider allowance.','blocking'),
('pipeline-validate:E_GAYOUT_REDIRECT_BLOCKED','Source redirected outside GayOut',
 'A source fetch redirected to a host outside the permitted HTTPS GayOut hosts. The external destination was not fetched as a GayOut source page.',
 'Review the original source URL and redirect before changing the permitted source contract.','blocking'),
('pipeline-validate:E_GAYOUT_SOURCE_BLOCKED','GayOut could not be read',
 'The available retrieval routes did not return a usable GayOut document. A security challenge or missing provider configuration is not treated as a successful empty import.',
 'Restore authorised source access or the configured extraction provider, then retry the sync.','blocking'),
('pipeline-validate:E_GAYOUT_SOURCE_GONE','Source page is no longer available',
 'The source returned HTTP 404 or 410. A detail URL is recorded as unavailable; this alone does not delete or archive a shared canonical venue, organisation or event.',
 'Check an official source before changing the canonical record status.','blocking'),
('pipeline-validate:E_GAYOUT_SOURCE_IDENTITY_INVALID','Source URL does not match the inventory',
 'The queued detail URL did not match a supported GayOut listing path for its venue, organisation or event inventory. No replacement identity was invented.',
 'Check the URL, inventory type and source path before retrying this item.','blocking'),
('pipeline-validate:E_GAYOUT_SOURCE_UNAVAILABLE','Source retrieval failed',
 'A network or extraction request failed before a usable source document was available. The pipeline cannot infer source facts from that failure.',
 'Check source and provider availability and retry from the saved checkpoint.','blocking'),
('pipeline-validate:E_GAYOUT_URL_INVALID','URL is not an allowed GayOut source',
 'The URL was not an HTTPS URL on the supported GayOut hosts, or contained credentials or an unsupported port. It was rejected before source acquisition.',
 'Use the public HTTPS GayOut listing or sitemap URL.','blocking'),
('pipeline-validate:E_SOURCE_DATE_OR_TIME_UNCONFIRMED','Event start time is not confirmed',
 'The source did not supply a valid explicit event start with a timezone. A date in a URL, a date-only field or an ambiguous local time is insufficient for automatic publication.',
 'Find a confirmed start time and timezone from an official event source before approving this occurrence.','blocking'),
('pipeline-validate:E_SOURCE_DATE_UNCONFIRMED','Event date is still to be announced',
 'The source explicitly marks the event date as unannounced. An older edition or structured date is not used to override that announcement.',
 'Wait for the organiser to confirm the date, then refresh the source record.','blocking'),
('pipeline-validate:E_SOURCE_FACTS_UNAVAILABLE','Listing facts could not be verified',
 'The page did not contain a usable structured listing identity. The pipeline held the item for review instead of inventing a name or location from its URL.',
 'Check the source page or an official website and add only corroborated factual fields.','blocking'),
('pipeline-validate:E_SOURCE_LOCATION_AND_CONTACT_MISSING','Listing needs a location or public contact',
 'The source supplied a name but no usable address, coordinate pair or public business contact. This is insufficient evidence for an automatic canonical record.',
 'Verify a physical location or published business contact and then revalidate the listing.','blocking'),
('pipeline-validate:E_GAYOUT_CHALLENGE','Source returned a security challenge',
 'The response is a security verification page rather than the requested GayOut content. It cannot supply inventory or listing facts.',
 'Restore an authorised retrieval route and retry; do not approve facts from the challenge page.','blocking'),
('pipeline-validate:E_GAYOUT_SITEMAP_INVALID','Source inventory is not a valid sitemap',
 'The inventory response did not contain the expected XML sitemap structure. Its cursor was not advanced as if the inventory had completed.',
 'Inspect the source response and sitemap location before retrying discovery.','blocking'),
('pipeline-validate:E_GAYOUT_SITEMAP_EMPTY','No supported source URLs were found',
 'A sitemap response contained no supported listing URLs or child sitemaps. This is reported as an inventory failure rather than proof that the source is fully synced.',
 'Check whether access failed or the source URL structure changed before retrying.','blocking'),
('pipeline-validate:E_GAYOUT_UNICODE_MATCH_REQUIRES_REVIEW','Names need an identity review',
 'A proposed canonical match would lose meaningful non-Latin name characters during ASCII normalisation. Distinct Unicode identities are held instead of being automatically merged.',
 'Compare the complete names, addresses and locations before approving a merge.','blocking'),
('pipeline-validate:E_GAYOUT_ORGANIZATION_COUNTRY_CONFLICT','Organisation countries disagree',
 'The proposed organisation match has a different known country from the new source record. The existing country is preserved and the item requires review.',
 'Check the organisation identity and official address before approving an update.','blocking')
on conflict(key) do nothing;
